/**
 * Worker entry point: wraps the OpenNext handler and adds a same-origin proxy
 * for the background remover's AI model.
 *
 * Why: Hugging Face doesn't send CORS headers for this site's origin, so the
 * browser refused the model download. Serving the files from /hf/... on our
 * own domain needs no CORS at all. Only the pinned model files are proxied,
 * so this can't be used as a general-purpose proxy.
 */

// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as nextHandler } from "./.open-next/worker.js";

const UPSTREAM = "https://huggingface.co";
const PREFIX = "/hf/";
/** model id → pinned revision that may be fetched */
const ALLOWED_MODELS: Record<string, string> = {
  "studioludens/birefnet-lite-512": "4a3c40c36c94093cc1e724d9ea428b8fa4b57dc7",
};
const YEAR = 31_536_000;

function isAllowed(path: string): boolean {
  // path looks like: <owner>/<name>/resolve/<revision>/<file...>
  if (path.includes("..") || path.includes("//")) return false;
  const match = /^([\w.-]+\/[\w.-]+)\/resolve\/([0-9a-f]{40})\/([\w./-]+)$/.exec(path);
  return Boolean(match && ALLOWED_MODELS[match[1]] === match[2]);
}

async function proxyModel(request: Request, path: string): Promise<Response> {
  if (request.method !== "GET" && request.method !== "HEAD") {
    return new Response("Method not allowed", { status: 405, headers: { Allow: "GET, HEAD" } });
  }
  if (!isAllowed(path)) return new Response("Not found", { status: 404 });

  const headers = new Headers();
  const range = request.headers.get("Range");
  if (range) headers.set("Range", range);

  const upstream = await fetch(`${UPSTREAM}/${path}`, {
    method: request.method,
    headers,
    redirect: "follow",
    // Pinned revisions never change, so Cloudflare may cache them for a year.
    cf: { cacheEverything: true, cacheTtl: YEAR },
  } as RequestInit);

  const out = new Headers();
  for (const name of ["content-type", "content-length", "content-range", "accept-ranges", "etag", "last-modified"]) {
    const value = upstream.headers.get(name);
    if (value) out.set(name, value);
  }
  out.set("Cache-Control", upstream.ok ? `public, max-age=${YEAR}, immutable` : "no-store");
  // Same-origin fetch from an isolated page: mark the response as same-origin only.
  out.set("Cross-Origin-Resource-Policy", "same-origin");
  return new Response(upstream.body, { status: upstream.status, headers: out });
}

export default {
  async fetch(request: Request, env: unknown, ctx: unknown): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname.startsWith(PREFIX)) {
      try {
        return await proxyModel(request, decodeURIComponent(url.pathname.slice(PREFIX.length)));
      } catch {
        return new Response("Model download failed", { status: 502, headers: { "Cache-Control": "no-store" } });
      }
    }
    return nextHandler.fetch(request, env, ctx);
  },
};
